/**
 * Expressions for lines of dialogue (v0.6.0).
 *
 * Visual novels change the sprite's expression line by line. The theatre does
 * the same for the page being read: a small keyword score (Chinese and
 * English) picks one of the expression artworks and a mood mark drawn above
 * her head. Code is ignored, and anything unclear stays neutral so the normal
 * state poses (thinking, answering, rice) keep showing.
 */
// Earlier rules win ties: surprise and frustration read more strongly than praise.
const EMOTION_RULES = [
    { emotion: 'surprised', pattern: /竟然|居然|没想到|原来如此|哇|诶[？?！!]|欸|咦|什么[？?！!]|真的吗|whoa|wow|surpris|unexpected|really\?|no way/gi },
    { emotion: 'surprised', pattern: /[？?][！!]|[！!][？?]/g, weight: 2 },
    { emotion: 'frustrated', pattern: /报错|错误|失败|崩溃|异常|不行|糟糕|可恶|气死|卡住|超时|bug|error|failed|failure|exception|crash|traceback|timeout|broken/gi },
    { emotion: 'shy', pattern: /抱歉|对不起|不好意思|害羞|脸红|羞|我错了|搞错了|sorry|apolog|embarrass|my mistake|my bad/gi },
    { emotion: 'happy', pattern: /太好了|开心|高兴|恭喜|哈哈|嘿嘿|好耶|喜欢|谢谢|感谢|辛苦了|棒|glad|great|happy|congrat|thank|awesome|nice|love|yay|😊|🎉|❤/gi },
    { emotion: 'proud', pattern: /完成|搞定|成功|解决了|修好了|没问题|大功告成|通过了|done|solved|success|fixed|works now|all set|passed/gi },
    { emotion: 'smug', pattern: /其实|当然|很简单|简单|小菜一碟|轻松|显然|不出所料|交给我|看我的|of course|simply|easy|actually|obviously|leave it to me|piece of cake/gi },
];
/** Prose only: fenced and inline code never sets her mood. */
function proseOf(text) {
    return text.replace(/```[\s\S]*?(```|$)/g, ' ').replace(/`[^`\n]*`/g, ' ');
}
function detectEmotion(text) {
    const prose = proseOf(text || '');
    if (!prose.trim())
        return 'neutral';
    const scores = new Map();
    for (const rule of EMOTION_RULES) {
        const hits = prose.match(rule.pattern)?.length ?? 0;
        if (hits)
            scores.set(rule.emotion, (scores.get(rule.emotion) ?? 0) + hits * (rule.weight ?? 1));
    }
    let best = 'neutral', bestScore = 0;
    for (const rule of EMOTION_RULES) {
        const score = scores.get(rule.emotion) ?? 0;
        if (score > bestScore) {
            best = rule.emotion;
            bestScore = score;
        }
    }
    return best;
}
/** Artwork for each expression (see poses.ts). */
const EMOTION_POSE = {
    happy: 'happy', proud: 'proud', smug: 'smug', shy: 'shy', surprised: 'surprised', frustrated: 'angry',
};
/** Mood mark above her head; a surprise phrased as a question gets “?”. */
function emoteFor(emotion, text = '') {
    switch (emotion) {
        case 'happy': return 'heart';
        case 'proud': return 'sparkle';
        case 'smug': return 'note';
        case 'shy': return 'sweat';
        case 'frustrated': return 'anger';
        case 'surprised': return /[！!]/.test(text) || !/[？?]/.test(text) ? 'exclaim' : 'question';
        default: return null;
    }
}

function dialogueBlocks(text) {
    const blocks = [];
    const pattern = /```([^\n`]*)\n([\s\S]*?)(?:```|$)/g;
    let offset = 0;
    for (const match of text.matchAll(pattern)) {
        if (match.index > offset)
            blocks.push({ kind: 'text', text: text.slice(offset, match.index) });
        blocks.push({ kind: 'code', language: match[1].trim(), text: match[2].replace(/\n$/, '') });
        offset = match.index + match[0].length;
    }
    if (offset < text.length)
        blocks.push({ kind: 'text', text: text.slice(offset) });
    return blocks;
}
function readConversationLog() {
    const nodes = Array.from(document.querySelectorAll('[data-chat-flow-kind="user-prompt"], [data-chat-flow-kind="assistant-step"]'));
    return nodes.filter(node => !nodes.some(other => other !== node && other.contains(node))).slice(-80).map(node => {
        return { role: node.getAttribute('data-chat-flow-kind') === 'user-prompt' ? 'user' : 'assistant', text: messageText(node).slice(0, 20000) };
    }).filter(entry => entry.text);
}
/** Preserve code and block boundaries while excluding reasoning and controls. */
function messageText(container) {
    const clone = container.cloneNode(true);
    clone.querySelectorAll('[data-variant="think"], [data-turn-process-inline], details.think, [class*="reasoning"], [class*="thought"], .summary, [class*="thinkBody"], button, [data-whale-pet]').forEach(el => el.remove());
    clone.querySelectorAll('strong, b').forEach(node => { if (!node.closest('pre'))
        node.replaceWith(document.createTextNode('**' + (node.textContent || '') + '**')); });
    clone.querySelectorAll('h1,h2,h3,h4').forEach(node => node.prepend(document.createTextNode('### ')));
    clone.querySelectorAll('pre').forEach(pre => {
        const code = pre.querySelector('code');
        const language = code?.className.match(/language-([\w+-]+)/)?.[1] || '';
        pre.replaceWith(document.createTextNode('\n```' + language + '\n' + (code?.textContent || pre.textContent || '') + '\n```\n'));
    });
    clone.querySelectorAll('li').forEach(node => { node.prepend(document.createTextNode('• ')); node.append(document.createTextNode('\n')); });
    clone.querySelectorAll('p, h1, h2, h3, h4, blockquote, br').forEach(node => node.append(document.createTextNode('\n')));
    const markdown = Array.from(clone.querySelectorAll('[class*="markdown"], [data-markdown-variant]')).filter(node => !node.parentElement?.closest('[class*="markdown"], [data-markdown-variant]'));
    return (markdown.length ? markdown.map(node => node.textContent || '').join('\n') : clone.textContent || '').trim();
}

function revealDelay(character, speed) {
    if (speed === 'instant')
        return 0;
    const base = speed === 'slow' ? 70 : speed === 'fast' ? 22 : 42;
    return /[。！？.!?]/.test(character) ? base * 7 : /[，,；;：:]/.test(character) ? base * 3 : /[…]/.test(character) ? base * 10 : base;
}
function diagnosticReport() {
    const selectors = { messages: '[data-chat-flow-kind]', generation: '[data-chat-running]', composer: '[data-composer-input], [data-composer-card], [data-composer-seat]', balances: '[class*="balanceCard"] [class*="amount"]' };
    return JSON.stringify({ plugin: 'dsh-whale-pet', checked: new Date().toISOString(), checks: Object.fromEntries(Object.entries(selectors).map(([key, selector]) => [key, { selector, matches: document.querySelectorAll(selector).length }])), note: 'Counts only. No message text, URL, account ID or credentials. Generation and balance may be absent while idle or closed.' }, null, 2);
}
/**
 * Wrap by measured line width rather than total characters, preserving all prose.
 * Widths are summed per character (one measurement per distinct character), so a
 * long streamed answer costs linear time instead of re-measuring every line prefix.
 */
function paginateText(text, width, height, font, charWidth) {
    const maxLines = Math.max(1, Math.floor(Math.max(28, height - 12) / (font * 1.75)));
    const limit = Math.max(font * 4, width);
    const measure = charWidth ?? ((c) => (/[\u0000-\u00ff]/.test(c) ? .58 : 1) * font);
    const pages = [];
    let page = '', lineWidth = 0, lineEmpty = true, lines = 1;
    for (const character of Array.from(text.replace(/\n{3,}/g, '\n\n'))) {
        const w = character === '\n' ? 0 : measure(character);
        if (character === '\n' || (!lineEmpty && lineWidth + w > limit)) {
            if (lines >= maxLines) {
                if (page.trim())
                    pages.push(page.trim());
                page = '';
                lines = 1;
            }
            else
                lines++;
            lineWidth = 0;
            lineEmpty = true;
        }
        page += character;
        if (character !== '\n') {
            lineWidth += w;
            lineEmpty = false;
        }
    }
    if (page.trim())
        pages.push(page.trim());
    return pages.length ? pages : ['……'];
}

